#!/usr/bin/env node
/**
 * Builds the standalone desktop executable.
 *
 *   1. bundle the browser app           public/js/bundle.js
 *   2. inline every public/ file        src/standalone/assets.generated.js
 *   3. bundle the server into one file  .build/lab.mjs
 *   4. append that script to node.exe   dist/RobloxExecutorLab-win-x64.exe
 *
 * Step 4 uses Node's Single Executable Application (SEA) mechanism: the script
 * is blatted into a copy of the real node.exe and the injected-main blob is
 * registered in the resource section with postject. The output is a genuine
 * 64-bit Windows console executable -- no Node install, no project folder, no
 * npm on the user's machine.
 *
 * Usage:
 *   node scripts/build-exe.js                # Windows x64 (default)
 *   node scripts/build-exe.js --linux        # Linux x64 (for testing here)
 *   node scripts/build-exe.js --skip-client  # reuse existing bundle.js
 */

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const BUILD = path.join(ROOT, '.build');
const DIST = path.join(ROOT, 'dist');

const args = new Set(process.argv.slice(2));
const TARGET_LINUX = args.has('--linux');
const SKIP_CLIENT = args.has('--skip-client');

const log = (msg) => console.log(`  ${msg}`);
const step = (n, msg) => console.log(`\n[${n}/4] ${msg}`);

/* ---------------------------------------------------------------------- */
/* helpers                                                                */
/* ---------------------------------------------------------------------- */

function runEsbuild(entry, outfile, extra = []) {
  const esbuild = path.join(ROOT, 'node_modules', '.bin', 'esbuild');
  execFileSync(esbuild, [
    entry,
    '--bundle',
    '--platform=node',
    '--format=esm',
    '--target=node20',
    `--outfile=${outfile}`,
    '--log-level=warning',
    ...extra,
  ], { cwd: ROOT, stdio: 'inherit' });
}

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
};

/** Walk public/ and return every regular file as a virtual path. */
function collectPublic(dir, base = dir, out = {}) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      collectPublic(full, base, out);
      continue;
    }
    const rel = `/${path.relative(base, full).split(path.sep).join('/')}`;
    // Source maps are for debugging the bundle in a checkout; they roughly
    // quadruple the exe for no benefit to an end user.
    if (rel.endsWith('.map')) continue;
    if (!(path.extname(rel) in MIME)) continue;
    out[rel] = fs.readFileSync(full, 'utf8');
  }
  return out;
}

/* ---------------------------------------------------------------------- */
/* 1. client bundle                                                       */
/* ---------------------------------------------------------------------- */

step(1, 'Bundling the browser app');
if (SKIP_CLIENT && fs.existsSync(path.join(ROOT, 'public/js/bundle.js'))) {
  log('reusing existing public/js/bundle.js');
} else {
  execFileSync(process.execPath, [path.join(ROOT, 'scripts/build.js')], { cwd: ROOT, stdio: 'inherit' });
}
const bundleBytes = fs.statSync(path.join(ROOT, 'public/js/bundle.js')).size;
log(`bundle.js ${(bundleBytes / 1024).toFixed(0)} kB`);

/* ---------------------------------------------------------------------- */
/* 2. embed assets                                                        */
/* ---------------------------------------------------------------------- */

step(2, 'Inlining public/ into the executable');
fs.mkdirSync(BUILD, { recursive: true });
const assets = collectPublic(path.join(ROOT, 'public'));
// Drop the source map reference: there is no .map file inside the exe.
if (assets['/js/bundle.js']) {
  assets['/js/bundle.js'] = assets['/js/bundle.js'].replace(/\n\/\/# sourceMappingURL=.*$/m, '\n');
}
const assetCount = Object.keys(assets).length;

// The server reads its assets off `globalThis.__LAB_ASSETS__`, populated here.
// Doing it through a generated module (rather than a dynamic import of a file
// that only exists during the build) keeps `node server/index.js` working in a
// plain checkout with no conditional bundling tricks.
const assetsModule = path.join(BUILD, 'assets.cjs');
fs.writeFileSync(
  assetsModule,
  `// AUTO-GENERATED by scripts/build-exe.js -- do not edit.\n`
  + `globalThis.__LAB_ASSETS__ = ${JSON.stringify(assets)};\n`
);
const assetsSize = fs.statSync(assetsModule).size;
log(`${assetCount} files, ${(assetsSize / 1024).toFixed(0)} kB embedded`);

/* ---------------------------------------------------------------------- */
/* 3. bundle the server                                                   */
/* ---------------------------------------------------------------------- */

step(3, 'Bundling the server');
// A tiny entry that installs the assets and then starts the server, bundled as
// CommonJS because that is the only main format Node's SEA loader understands.
const seaEntry = path.join(BUILD, 'sea-entry.cjs');
fs.writeFileSync(seaEntry, [
  `require(${JSON.stringify(assetsModule)});`,
  `require(${JSON.stringify(path.join(ROOT, 'server/index.js'))});`,
  '',
].join('\n'));

const serverBundle = path.join(BUILD, 'lab.cjs');
execFileSync(path.join(ROOT, 'node_modules', '.bin', 'esbuild'), [
  seaEntry,
  '--bundle',
  '--platform=node',
  '--format=cjs',
  '--target=node20',
  `--outfile=${serverBundle}`,
  '--log-level=warning',
], { cwd: ROOT, stdio: 'inherit' });
const serverSize = fs.statSync(serverBundle).size;
log(`lab.cjs ${(serverSize / 1024).toFixed(0)} kB`);

/* ---------------------------------------------------------------------- */
/* 4. build the executable                                                */
/* ---------------------------------------------------------------------- */

step(4, `Building ${TARGET_LINUX ? 'linux-x64' : 'win-x64'} executable`);
fs.mkdirSync(DIST, { recursive: true });

const nodeBinary = path.join(BUILD, TARGET_LINUX ? 'node-linux-x64' : 'node-win-x64.exe');
if (!fs.existsSync(nodeBinary)) {
  if (TARGET_LINUX) {
    fs.copyFileSync(process.execPath, nodeBinary);
  } else {
    // Fetched by scripts/fetch-node-win.js in a normal build; fail loudly here
    // rather than producing an exe that silently cannot start.
    console.error('  missing .build/node-win-x64.exe');
    console.error('  run: node scripts/fetch-node-win.js');
    process.exit(1);
  }
}

const outFile = path.join(
  DIST,
  TARGET_LINUX ? 'RobloxExecutorLab-linux-x64' : 'RobloxExecutorLab-win-x64.exe'
);
fs.copyFileSync(nodeBinary, outFile);

// node --experimental-sea-config generates the blob describing what to inject
const seaConfig = path.join(BUILD, 'sea-config.json');
fs.writeFileSync(seaConfig, JSON.stringify({
  main: serverBundle,
  output: path.join(BUILD, 'sea-prep.blob'),
  disableExperimentalSEAWarning: true,
  useSnapshot: false,
  useCodeCache: false,
}, null, 2));

execFileSync(process.execPath, [
  '--experimental-sea-config', seaConfig,
], { cwd: ROOT, stdio: 'inherit' });

// Inject the blob. Flag set differs per platform: --macho-segment-name is a
// macOS-only concept and passing it for a PE file is meaningless.
const postject = path.join(ROOT, 'node_modules', '.bin', 'postject');
const postjectArgs = [
  outFile,
  'NODE_SEA_BLOB',
  path.join(BUILD, 'sea-prep.blob'),
  '--sentinel-fuse', 'NODE_SEA_FUSE_fce680ab2cc467b6e072b8b5df1996b2',
  '--overwrite',
];
if (process.platform === 'darwin') postjectArgs.push('--macho-segment-name', 'NODE_SEA');
execFileSync(postject, postjectArgs, { cwd: ROOT, stdio: 'inherit' });

const finalSize = fs.statSync(outFile).size;
log(`${path.relative(ROOT, outFile)} ${(finalSize / 1024 / 1024).toFixed(1)} MB`);

/* ---------------------------------------------------------------------- */

fs.rmSync(assetsModule, { force: true });
console.log(`\n  Done. Run ${path.basename(outFile)} — it opens http://localhost:5173 in your browser.\n`);
